    /**
     * Tests creating a new InvestmentProgram.
     *
     * @return    InvestmentProgram
     */
    public InvestmentProgram testCreate() throws Throwable {
    InvestmentProgram entity = null;

    LOGGER.info( "InvestmentProgramTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a InvestmentProgram");

    StringBuilder msg = new StringBuilder( "-- Failed to create a InvestmentProgram" );

    try {
        entity = service.createInvestmentProgram( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getInvestmentProgramId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a InvestmentProgram with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a InvestmentProgram.
     *
     * @return    InvestmentProgram
     */
    public InvestmentProgram testRead() throws Throwable {
    LOGGER.info( "InvestmentProgramTest:testRead()" );
    LOGGER.info( "-- Reading a previously created InvestmentProgram" );

    InvestmentProgram entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read InvestmentProgram with primary key" );
    msg.append( theId );

    try {
        entity = service.getInvestmentProgram( new InvestmentProgramFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getInvestmentProgramId();

        LOGGER.info( "-- Successfully found InvestmentProgram " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a InvestmentProgram.
     *
     * @return    InvestmentProgram
     */
    public InvestmentProgram testUpdate() throws Throwable {
    LOGGER.info( "InvestmentProgramTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a InvestmentProgram." );

    StringBuilder msg = new StringBuilder( "Failed to update a InvestmentProgram : " );
    InvestmentProgram entity = null;

    try {
        UpdateInvestmentProgramCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setInvestmentProgramId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created InvestmentProgram." );

        entity = service.updateInvestmentProgram( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved InvestmentProgram - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a InvestmentProgram.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "InvestmentProgramTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created InvestmentProgram." );

    try {
        DeleteInvestmentProgramCommand deleteCommand = new DeleteInvestmentProgramCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted InvestmentProgram with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete InvestmentProgram with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all InvestmentPrograms.
     *
     * @return    Collection
     */
    public List<InvestmentProgram> testGetAll() throws Throwable {
    LOGGER.info( "InvestmentProgramTest:testGetAll() - Retrieving Collection of InvestmentPrograms:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all InvestmentProgram : " );
    List<InvestmentProgram> collection  = null;

    try {
        // call the static get method on the InvestmentProgramService
        collection = service.getAllInvestmentProgram();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            InvestmentProgram currEntity  = null;
            Iterator<InvestmentProgram> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInvestmentProgramId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

